package com.fittrack.auth; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="refresh_tokens",indexes={@Index(name="idx_refresh_hash",columnList="token_hash",unique=true),@Index(name="idx_refresh_tokens_family",columnList="family_id")}) public class RefreshToken { @Id UUID id; @Column(nullable=false) UUID userId; @Column(nullable=false) String tokenHash; @Column(nullable=false) UUID familyId; @Column(nullable=false) Instant expiresAt; @Column(nullable=false) boolean revoked; @Column(nullable=false) boolean used; @Column String replacedByHash; public UUID getId(){return id;} public UUID getUserId(){return userId;} public void setUserId(UUID v){userId=v;} public String getTokenHash(){return tokenHash;} public void setTokenHash(String v){tokenHash=v;} public UUID getFamilyId(){return familyId;} public void setFamilyId(UUID v){familyId=v;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant v){expiresAt=v;} public boolean isRevoked(){return revoked;} public void setRevoked(boolean v){revoked=v;} public boolean isUsed(){return used;} public void setUsed(boolean v){used=v;} public void setReplacedByHash(String v){replacedByHash=v;} @PrePersist void init(){if(id==null)id=UUID.randomUUID();if(familyId==null)familyId=id;} }
